css:
.cocreatesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2433;
    background: linear-gradient(160deg, #f5f3ee 0%, #ece7dd 100%);
    border-radius: 18px;
}

.cocreatesim-container * {
    box-sizing: border-box;
}

.cocreatesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #16213e 0%, #1f335c 55%, #2c4a7a 100%);
    color: #f7f4ec;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 33, 62, 0.32);
    border-bottom: 4px solid #c89b3c;
}

.cocreatesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.cocreatesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0d79a;
    background: rgba(200, 155, 60, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.cocreatesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3ddd0;
}

.cocreatesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2f3a52;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cocreatesim-period-counter #currentDay,
.cocreatesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #16213e;
}

.cocreatesim-round-name {
    background: #e5dcc4;
    color: #6b4e15;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cocreatesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3517;
    background: #f6e0d6;
    padding: 4px 12px;
    border-radius: 999px;
}

.cocreatesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cocreatesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.06);
    border-top: 4px solid #2c4a7a;
}

.cocreatesim-card-fit { border-top-color: #2c4a7a; }
.cocreatesim-card-impact { border-top-color: #8a5fb0; }
.cocreatesim-card-trust { border-top-color: #1c7a5e; }
.cocreatesim-card-margin { border-top-color: #c89b3c; }

.cocreatesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #76705f;
}

.cocreatesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16213e;
}

.cocreatesim-card-fit .cocreatesim-value { color: #2c4a7a; }
.cocreatesim-card-impact .cocreatesim-value { color: #8a5fb0; }
.cocreatesim-card-trust .cocreatesim-value { color: #1c7a5e; }
.cocreatesim-card-margin .cocreatesim-value { color: #b07f1e; }

.cocreatesim-sublabel {
    font-size: 0.76rem;
    color: #837c6b;
    line-height: 1.35;
}

.cocreatesim-fit-target .cocreatesim-value { color: #1c7a5e; }
.cocreatesim-fit-low .cocreatesim-value { color: #c0392b; }
.cocreatesim-impact-target .cocreatesim-value { color: #6d3fa0; }
.cocreatesim-impact-low .cocreatesim-value { color: #c0392b; }
.cocreatesim-margin-thin .cocreatesim-value { color: #c0392b; }

.cocreatesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16213e;
    color: #f0ece0;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.cocreatesim-budget-bar #budgetDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #f0d79a;
}

.cocreatesim-budget-over #budgetDisplay {
    color: #ff9a87;
}

.cocreatesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c89b3c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.05);
}

.cocreatesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cocreatesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16213e;
    margin-bottom: 6px;
}

.cocreatesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #39405a;
}

.cocreatesim-briefing-text strong { color: #1c7a5e; }
.cocreatesim-briefing-text em { color: #9a3517; font-style: italic; }

.cocreatesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.06);
}

.cocreatesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16213e;
    border-bottom: 2px solid #ece7dd;
    padding-bottom: 8px;
}

.cocreatesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #283150;
    margin: 14px 0 6px;
}

.cocreatesim-container select,
.cocreatesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc4ad;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8f2;
    color: #1f2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cocreatesim-container select:focus,
.cocreatesim-container input[type="number"]:focus {
    outline: none;
    border-color: #c89b3c;
    box-shadow: 0 0 0 3px rgba(200, 155, 60, 0.18);
}

.cocreatesim-container select option {
    background-color: #ffffff;
    color: #1f2433;
}

.cocreatesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c89b3c;
}

.cocreatesim-range-readout,
.cocreatesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c4a7a;
    margin-top: 4px;
}

.cocreatesim-range-readout span:last-child,
.cocreatesim-alloc-readout span:nth-child(2) {
    color: #b07f1e;
    font-weight: 800;
}

.cocreatesim-hint {
    font-size: 0.8rem;
    color: #837c6b;
    margin-top: 4px;
    line-height: 1.4;
}

.cocreatesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.cocreatesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f4ec;
    border: 1px solid #e7e0cf;
    border-radius: 9px;
    padding: 8px 12px;
}

.cocreatesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #283150;
}

.cocreatesim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.cocreatesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cocreatesim-container .btn-primary {
    background: linear-gradient(135deg, #16213e 0%, #2c4a7a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(22, 33, 62, 0.28);
}

.cocreatesim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.cocreatesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdc4ad;
    color: #76705f;
}

.cocreatesim-coach {
    background: #16213e;
    color: #f0ece0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 33, 62, 0.22);
    border-left: 5px solid #c89b3c;
}

.cocreatesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0d79a;
    margin-bottom: 8px;
}

.cocreatesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cocreatesim-coach-body strong { color: #f5d98a; }
.cocreatesim-coach-body em { color: #ffb59c; font-style: italic; }

.cocreatesim-history,
.cocreatesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.06);
}

.cocreatesim-history h3,
.cocreatesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16213e;
}

.cocreatesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #283150;
}

.cocreatesim-container table#usfHistoryTable th {
    background: #f1ece0;
    color: #16213e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3dac4;
}

.cocreatesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebe0;
}

.cocreatesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.cocreatesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cocreatesim-container {
        padding: 14px;
    }
    .cocreatesim-header h1 {
        font-size: 1.7rem;
    }
    .cocreatesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cocreatesim-value {
        font-size: 2rem;
    }
    .cocreatesim-clock {
        margin-left: 0;
    }
    .cocreatesim-period-counter {
        font-size: 0.88rem;
    }
    .cocreatesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cocreatesim-alloc-row {
        flex-wrap: wrap;
    }
    .cocreatesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .cocreatesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) — self-contained, readable on the white modal */
.cocreatesim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #241a33; }
.cocreatesim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(36,26,51,0.15); margin-bottom: 16px; }
.cocreatesim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #6a3fa0; }
.cocreatesim-cm-score-max { font-size: 18px; font-weight: 600; color: #574a6e; margin-left: 2px; }
.cocreatesim-cm-grade { font-size: 18px; font-weight: 700; color: #241a33; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.cocreatesim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.cocreatesim-cm-yes { background: rgba(106,63,160,0.16); color: #573497; }
.cocreatesim-cm-no { background: rgba(176,51,37,0.12); color: #b03325; }
.cocreatesim-cm-warn { background: rgba(180,110,20,0.16); color: #8a5410; }
.cocreatesim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.cocreatesim-cm-metric { flex: 1 1 110px; background: #f0eef6; border: 1px solid rgba(36,26,51,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.cocreatesim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #241a33; }
.cocreatesim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #574a6e; margin-top: 2px; }
.cocreatesim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #574a6e; margin-bottom: 8px; }
.cocreatesim-cm-insights { margin: 0; padding-left: 20px; }
.cocreatesim-cm-insights li { font-size: 14px; line-height: 1.5; color: #2e2440; margin-bottom: 8px; }

