(function() {
    'use strict';

    class CoCreateAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Co-Creating the Programme`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Trinity Quad × Helvern) ----
            this.CONTRACT = 680;            // £680k fixed envelope, in £k
            this.BUDGET_CAP = 680;          // design cost cap, £k
            this.PARTICIPANTS = 90;         // 3 cohorts × 30
            this.AS_DESIGNED_PP = 7556;     // £680k ÷ 90
            this.BENCHMARK_PP = 5500;       // rival benchmark per participant
            this.SUCCESS_FEE = 68;          // £68k (10%) impact-linked, £k
            this.START_MARGIN = 32;         // 32% contribution margin
            this.CORE_RATE = 2.2;           // £2,200/day, in £k
            this.STAR_RATE = 4.5;           // £4,500/day, in £k
            this.BUILD_COST = 120;          // fixed design + measurement build, £k
            this.FIT_TARGET = 70;           // diagnosis-fit win threshold
            this.IMPACT_TARGET = 65;        // impact-credibility win threshold

            // Concept-correct answers.
            this.TRUE_DIAG = `triangulate`;
            this.TRUE_CAP = `aligned`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fit: 20,
                    impact: 15,
                    trust: 45,
                    margin: this.START_MARGIN,
                    budgetUsed: 0,
                    feeReleased: false,
                    feeForfeited: false,
                    overBudget: false,
                    cohortsLost: false,
                    fitHistory: [20],
                    impactHistory: [15],
                    trustHistory: [45],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    diag: `triangulate`,
                    cap: `aligned`,
                    recontract: 60,
                    pedagogy: `seventy`,
                    core: 60,
                    star: 12,
                    format: `hybrid`,
                    price: `defend`,
                    fee: `behaviour`,
                    descope: 15,
                    gap: `rebrief`,
                    measure: `hybrid`,
                    cohorts: `adjust`,
                    quality: 65
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const diag = document.getElementById(`diagInput`);
                const cap = document.getElementById(`capInput`);
                const rc = document.getElementById(`recontractInput`);
                if (diag) decisions.diag = diag.value;
                if (cap) decisions.cap = cap.value;
                if (rc) decisions.recontract = parseInt(rc.value, 10);
                if (!Number.isFinite(decisions.recontract) || decisions.recontract < 0 || decisions.recontract > 100) {
                    warn(`warn_recontract_range`); return false;
                }
            } else if (round === 2) {
                const ped = document.getElementById(`pedagogyInput`);
                const core = document.getElementById(`coreInput`);
                const star = document.getElementById(`starInput`);
                const fmt = document.getElementById(`formatInput`);
                if (ped) decisions.pedagogy = ped.value;
                if (core) decisions.core = parseFloat(core.value);
                if (star) decisions.star = parseFloat(star.value);
                if (fmt) decisions.format = fmt.value;
                if (!Number.isFinite(decisions.core) || decisions.core < 0) {
                    warn(`warn_core_negative`); return false;
                }
                if (!Number.isFinite(decisions.star) || decisions.star < 0) {
                    warn(`warn_star_negative`); return false;
                }
                if (decisions.core + decisions.star < 20) {
                    warn(`warn_faculty_min`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`priceInput`);
                const fe = document.getElementById(`feeInput`);
                const de = document.getElementById(`descopeInput`);
                if (pr) decisions.price = pr.value;
                if (fe) decisions.fee = fe.value;
                if (de) decisions.descope = parseInt(de.value, 10);
                if (!Number.isFinite(decisions.descope) || decisions.descope < 0 || decisions.descope > 100) {
                    warn(`warn_descope_range`); return false;
                }
            } else if (round === 4) {
                const gp = document.getElementById(`gapInput`);
                const me = document.getElementById(`measureInput`);
                const co = document.getElementById(`cohortsInput`);
                const ql = document.getElementById(`qualityInput`);
                if (gp) decisions.gap = gp.value;
                if (me) decisions.measure = me.value;
                if (co) decisions.cohorts = co.value;
                if (ql) decisions.quality = parseInt(ql.value, 10);
                if (!Number.isFinite(decisions.quality) || decisions.quality < 0 || decisions.quality > 100) {
                    warn(`warn_quality_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fitDelta = 0, impactDelta = 0, trustDelta = 0, marginDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the real challenge before designing (Common Error 1).
                switch (d.diag) {
                    case `triangulate`: fitDelta += 18; trustDelta += 6; coachKey = `coach_r1_triangulate`; break;
                    case `ceo`: fitDelta += 4; trustDelta += 2; coachKey = `coach_r1_ceo`; break;
                    case `design`: fitDelta -= 12; trustDelta -= 6; coachKey = `coach_r1_design`; break;
                }

                // Backward design: capabilities tied to the outcome and the success measure.
                switch (d.cap) {
                    case `aligned`: fitDelta += 11; impactDelta += 6; if (d.diag === `triangulate`) coachKey = `coach_r1_sharp`; break;
                    case `generic`: fitDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r1_generic` : coachKey; break;
                    case `content`: fitDelta -= 10; impactDelta -= 4; coachKey = `coach_r1_content`; break;
                }

                // Re-contracting call: separate the request from the need before quoting.
                if (d.recontract >= 60) { fitDelta += 6; trustDelta += 4; }
                else if (d.recontract <= 25) { fitDelta -= 6; coachKey = `coach_r1_norecontract`; }

                summaryKey = (d.diag === this.TRUE_DIAG && d.cap === this.TRUE_CAP) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Co-configure the journey within the £680k envelope.
                // Pedagogy: 70-20-10 embeds workplace application + coaching (Key Concept).
                switch (d.pedagogy) {
                    case `seventy`: impactDelta += 18; fitDelta += 4; coachKey = `coach_r2_seventy`; break;
                    case `balanced`: impactDelta += 5; fitDelta += 2; coachKey = `coach_r2_balanced`; break;
                    case `teaching`: impactDelta -= 10; coachKey = `coach_r2_teaching`; break;
                }

                // Faculty: relevance vs scarcity/cost. Some star days lift relevance; an all-core
                // design is cheap but under-powered; an all-star design blows the budget.
                const facultySpend = d.core * this.CORE_RATE + d.star * this.STAR_RATE;
                spend += facultySpend;
                if (d.star >= 8 && d.star <= 24 && d.core >= 40) {
                    fitDelta += 5; impactDelta += 4;
                } else if (d.star > 36) {
                    fitDelta += 3; coachKey = `coach_r2_starheavy`;
                } else if (d.star === 0) {
                    fitDelta -= 4; coachKey = (coachKey === `coach_r2_teaching`) ? coachKey : `coach_r2_allcore`;
                }

                // Format: hybrid balances reach, cost and behaviour change; residential is premium
                // and budget-hungry; virtual-only is cheap but weak on application.
                switch (d.format) {
                    case `hybrid`: spend += 170; impactDelta += 10; fitDelta += 3; break;
                    case `residential`: spend += 260; impactDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r2_residential` : coachKey; break;
                    case `virtual`: spend += 80; impactDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r2_virtual` : coachKey; break;
                }

                spend += this.BUILD_COST; // fixed design + measurement build

                summaryKey = (d.pedagogy === `seventy` && d.format !== `virtual`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Defend the design and the price premium (Common Error 3).
                switch (d.price) {
                    case `defend`: trustDelta += 12; impactDelta += 4; marginDelta += 0; coachKey = `coach_r3_defend`; break;
                    case `cave`:
                        // Match £5,500 by stripping action-learning + coaching: protects price,
                        // destroys the impact the £68k fee depends on.
                        trustDelta += 2; impactDelta -= 18; marginDelta -= 4; coachKey = `coach_r3_cave`;
                        break;
                    case `rigid`: trustDelta -= 12; coachKey = `coach_r3_rigid`; break;
                }

                // Success fee: tying to Behaviour/Results changes design and price (Kirkpatrick).
                switch (d.fee) {
                    case `behaviour`: impactDelta += 12; trustDelta += 4; if (d.price === `defend`) coachKey = `coach_r3_strong`; break;
                    case `renegotiate`: impactDelta -= 6; coachKey = (coachKey === `coach_r3_defend`) ? `coach_r3_renegotiate` : coachKey; break;
                    case `drop`: impactDelta -= 12; trustDelta -= 4; coachKey = `coach_r3_dropfee`; break;
                }

                // De-scope: a small managed concession is fine; a deep cut strips impact and signals
                // the design was padded.
                if (d.descope <= 20) { trustDelta += 2; }
                else if (d.descope >= 50) { impactDelta -= 10; trustDelta -= 4; coachKey = `coach_r3_overdescope`; }
                else { impactDelta -= 3; }

                summaryKey = (d.price === `defend` && d.fee === `behaviour`) ? `sum_r3_good` : (d.price === `cave` ? `sum_r3_discount` : `sum_r3_weak`);
            } else if (round === 4) {
                // Deliver and prove impact (Common Errors 4 & 5).
                // Faculty drop-out: resourcing is a quality decision, not just logistics.
                switch (d.gap) {
                    case `rebrief`: fitDelta += 8; trustDelta += 8; impactDelta += 2; coachKey = `coach_r4_rebrief`; break;
                    case `silent`: fitDelta -= 6; trustDelta -= 12; impactDelta -= 6; coachKey = `coach_r4_silent`; break;
                    case `delay`: trustDelta -= 14; coachKey = `coach_r4_delay`; break;
                }

                // Impact measurement that releases the £68k fee (Kirkpatrick levels).
                switch (d.measure) {
                    case `hybrid`: impactDelta += 16; trustDelta += 6; ds.feeReleased = true; coachKey = (d.gap === `rebrief`) ? `coach_r4_hybrid` : coachKey; break;
                    case `happy`: impactDelta -= 14; ds.feeForfeited = true; coachKey = `coach_r4_happy`; break;
                    case `kpionly`: impactDelta += 4; trustDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_kpionly` : coachKey; break;
                }

                // Cohorts 2-3 recommendation.
                switch (d.cohorts) {
                    case `adjust`: trustDelta += 8; fitDelta += 4; break;
                    case `repeat`: fitDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_repeat` : coachKey; break;
                    case `pause`: trustDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_pause` : coachKey; break;
                }

                // Protecting learning quality despite patchy attendance.
                if (d.quality >= 60) { impactDelta += 6; fitDelta += 2; }
                else if (d.quality <= 30) { impactDelta -= 8; trustDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_lowquality` : coachKey; }

                summaryKey = (d.gap === `rebrief` && d.measure === `hybrid` && d.cohorts === `adjust`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Resource accounting ----
            if (spend > 0) {
                ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            }
            // Over-budget: the design cannot land at £7,556, let alone defend a premium.
            // Erodes margin and trust; the client (or you) must cut.
            if (round === 2 && ds.budgetUsed > this.BUDGET_CAP) {
                ds.overBudget = true;
                const over = ds.budgetUsed - this.BUDGET_CAP;
                marginDelta -= Math.min(10, 4 + over / 25);
                trustDelta -= 6;
                fitDelta -= 4;
                if (coachKey === `coach_default` || coachKey === `coach_r2_residential` || coachKey === `coach_r2_starheavy`) coachKey = `coach_r2_overbudget`;
            }

            // ---- Apply deltas with headroom (no early saturation) ----
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.margin = Math.max(0, Math.min(45, ds.margin + marginDelta));

            ds.fitHistory.push(Math.round(ds.fit));
            ds.impactHistory.push(Math.round(ds.impact));
            ds.trustHistory.push(Math.round(ds.trust));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            // Final-round fee logic safeguard: an impact below target cannot truly release the fee.
            if (round === this.ROUNDS.length) {
                if (ds.impact < this.IMPACT_TARGET) ds.feeReleased = false;
                if (ds.trust < 40) ds.cohortsLost = true;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                margin: Math.round(ds.margin),
                budgetUsed: ds.budgetUsed,
                feeReleased: ds.feeReleased,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

