        // Composite (0-100) VERBATIM from v1.0.0 getPerformanceSummary; written to
        // domainState.performance.overallScore each period for the reporting/grading layer.
        _composite(ds) {
            var fit = Math.round(ds.fit || 0);
            var impact = Math.round(ds.impact || 0);
            var trust = Math.round(ds.trust || 0);
            var margin = Math.round(ds.margin || 0);
            return Math.round(fit * 0.30 + impact * 0.30 + trust * 0.25 + Math.min(100, margin * 2.6) * 0.15);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fit);
            const impact = Math.round(ds.impact);
            const trust = Math.round(ds.trust);
            const margin = Math.round(ds.margin);

            const hitFit = fit >= this.FIT_TARGET;
            const hitImpact = impact >= this.IMPACT_TARGET;
            const feeReleased = ds.feeReleased && hitImpact;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_missold`;
            if (hitFit && hitImpact && trust >= 60 && composite >= 72) performanceKey = `grade_flagship`;
            else if (hitFit && hitImpact && trust >= 55) performanceKey = `grade_credible`;
            else if (hitFit && !hitImpact) performanceKey = `grade_unproven`;
            else if (!hitFit && trust >= 55) performanceKey = `grade_liked`;
            else if (fit > 45 || impact > 40) performanceKey = `grade_improving`;
            const performance = T(performanceKey);

            const insights = [];
            if (feeReleased) insights.push(window.mySimulation.t(`insight_fee`));
            else insights.push(window.mySimulation.t(`insight_nofee`));

            if (hitFit && hitImpact && trust >= 60) insights.push(window.mySimulation.t(`insight_flagship`));
            else if (hitFit && !hitImpact) insights.push(window.mySimulation.t(`insight_thinimpact`));
            else if (!hitFit) insights.push(window.mySimulation.t(`insight_offtarget`));

            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (margin < 24) insights.push(window.mySimulation.t(`insight_thinmargin`));
            if (ds.cohortsLost) insights.push(window.mySimulation.t(`insight_cohortslost`));
            else if (hitImpact && trust >= 60) insights.push(window.mySimulation.t(`insight_renewal`));

            return {
                fit: fit,
                impact: impact,
                trust: trust,
                margin: margin,
                feeReleased: feeReleased,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                overBudget: ds.overBudget,
                cohortsLost: ds.cohortsLost,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var ok = !!s.feeReleased;
            var badge = ok
                ? '<span class="cocreatesim-cm-badge cocreatesim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="cocreatesim-cm-badge cocreatesim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (s.overBudget || s.cohortsLost)
                ? '<span class="cocreatesim-cm-badge cocreatesim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="cocreatesim-cm-metric"><span class="cocreatesim-cm-mv">' + Math.round(s.fit || 0) + '</span><span class="cocreatesim-cm-ml">' + T('cm_m_fit') + '</span></div>'
                + '<div class="cocreatesim-cm-metric"><span class="cocreatesim-cm-mv">' + Math.round(s.impact || 0) + '</span><span class="cocreatesim-cm-ml">' + T('cm_m_impact') + '</span></div>'
                + '<div class="cocreatesim-cm-metric"><span class="cocreatesim-cm-mv">' + Math.round(s.trust || 0) + '</span><span class="cocreatesim-cm-ml">' + T('cm_m_trust') + '</span></div>'
                + '<div class="cocreatesim-cm-metric"><span class="cocreatesim-cm-mv">' + Math.round(s.margin || 0) + '%</span><span class="cocreatesim-cm-ml">' + T('cm_m_margin') + '</span></div>';
            return ''
                + '<div class="cocreatesim-completion">'
                +   '<div class="cocreatesim-cm-head">'
                +     '<div class="cocreatesim-cm-score">' + score + '<span class="cocreatesim-cm-score-max">/100</span></div>'
                +     '<div class="cocreatesim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   '<div class="cocreatesim-cm-metrics">' + metrics + '</div>'
                +   '<div class="cocreatesim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="cocreatesim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

