                    warn_faculty_min:       `Un recorrido creíble necesita al menos 20 jornadas de profesorado entre las tres cohortes. Añade más.`,
                    warn_descope_range:     `La concesión de reducción de alcance debe ser un porcentaje entre 0 y 100.`,
